/*
 * A045726  Fibonacci numbers having initial digit '2'.
 * https://oeis.org/A045726
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 5, u32 n <= 9, u64 n <= 17, u128 n <= 33,
 *            big any n
 * Helpers:   digit_len, pow10
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A045726 – Fibonacci numbers whose first decimal digit is '2'.
 *  a(1) = 2, a(2) = 21, a(3) = 233, …                                           
 *  The sequence is generated by scanning successive Fibonacci numbers
 *  and collecting those whose most significant digit is 2.  Since
 *  leading digits of Fibonacci numbers satisfy Benford's law, the
 *  density near 30 % guarantees that the nth such number is found after
 *  at most about n/0.3 Fibonacci terms – well within the limits for
 *  n ≤ 10 000.  This implementation uses only integer arithmetic;
 *  it relies on the helper functions:
 *      digit_len(seq_t x) – number of decimal digits of x
 *      pow10(idx_t e)     – 10^e as seq_t
 *      fib(n)             – (optional) direct Fibonacci
 */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/pow10.h"
#include "../utils/digit_len.h"

/*  External linkage as required by the build system.  */
seq_t a(idx_t n)
{
    /*  Fibonacci iteration: F(0)=0, F(1)=1.  */
    seq_t prev = 0;
    seq_t curr = 1;

    idx_t count = 0;          /* how many 2-leading Fibonacci numbers found */

    /*  Search until we locate the n‑th such number.  */
    while (1) {
        seq_t f = curr;       /* current Fibonacci number */

        /*  Determine most significant digit without any floating point
         *  arithmetic:  divide by 10^(num_digits-1).  */
        int digits = digit_len(f);                 /* decimal digit count */
        seq_t ten_pow = pow10((idx_t)(digits - 1));
        seq_t lead = f / ten_pow;                  /* leading digit */

        if (lead == 2) {
            ++count;
            if (count == n)
                return f;                         /* desired member found */
        }

        /*  Advance to next Fibonacci number.  */
        seq_t next = prev + curr;
        prev = curr;
        curr = next;
    }
}
